f71\u54cd\u4f46\u4ecd\u53ef\u89e3\u91ca\uff08\u89c1\u6d88\u878d A\uff09 |\n| U5 | \u5b98\u65b9 EM/ES \u811a\u672c\u7684\u5f52\u4e00\u5316\u7ec6\u8282 | \u5b98\u65b9 `evaluate.py` \u6e90\u7801\uff08EM \u662f\u5426\u53bb\u7a7a\u767d/\u6ce8\u91ca/\u5927\u5c0f\u5199\uff1bES \u7684 Levenshtein \u5b9e\u73b0\u4e0e\u5206\u6bcd\uff09 | \u81ea\u5efa\u5e76\u56fa\u5b9a\u5f52\u4e00\u5316\uff08\u89c1 \u00a72.3\uff09\uff0c\u7528\u5355\u5143\u6d4b\u8bd5\u9501\u5b9a | \u5f52\u4e00\u5316\u5f71\u54cd\u7edd\u5bf9 EM\uff1bES \u5bf9\u5f52\u4e00\u5316\u8f83\u7a33\u5065\uff1b\u76f8\u5bf9\u6bd4\u8f83\u4e0e\u663e\u8457\u6027\u4e3b\u8981\u53d7 ES \u9a71\u52a8\uff1b\u62a5\u544a\u4e2d\u58f0\u660e\u53e3\u5f84 |\n| U6 | \u65e2\u6709\u6587\u732e\u4e2d GPT-2 / CodeLlama-7B \u5728 RepoBench-P \u7684\u5177\u4f53\u6570\u503c | \u5b98\u65b9 issues\u3001\u540e\u7eed\u590d\u73b0\u6587\u732e(\u5982 RepoFusion/LongCoder \u8868\u683c)\u3001BigCodeBench \u7b49 | \u4f5c\u4e3a sanity-check \u53c2\u8003\u800c\u975e\u7ed3\u8bba\u4f9d\u636e\uff1b\u4e0d\u53ef\u5f97\u5219\u6ce8\u660e\u672c\u8bbe\u8ba1\u4e0d\u4f9d\u8d56\u5916\u90e8\u590d\u73b0\u6570\u5b57 | \u4f4e\uff1a\u4ec5\u4f5c\u5bf9\u7167\u9a8c\u8bc1\u6a21\u578b\u7ba1\u7ebf\u6b63\u786e\u6027 |\n| U7 | \u6a21\u578b\u6743\u91cd/\u8bc4\u6d4b\u7248\u672c\u7684\u53ef\u590d\u73b0\u6807\u8bc6 | HF \u6743\u91cd sha256\u3001transformers/torch/Python \u7248\u672c\u3001\u6570\u636e\u96c6 commit hash | \u82e5\u4e0d\u53ef\u79bb\u7ebf\u9501\u5b9a\uff0c\u5728\u62a5\u544a\u4e2d\u8bb0\u5f55\u7248\u672c\u5b57\u7b26\u4e32 | \u5f71\u54cd\u7edd\u5bf9\u590d\u73b0\u6027\uff0c\u4e0d\u5f71\u54cd\u7ed3\u8bba\u65b9\u5411 |\n\n---\n\n## 2. \u5de5\u4f5c\u65b9\u6cd5\uff08\u6b63\u5f0f\u7248\uff09\n\n### 2.1 \u5b9e\u9a8c\u89c4\u6a21\u4e0e\u914d\u5bf9\u8bbe\u8ba1\n- **\u6570\u636e\u96c6**\uff1aRepoBench-P \u5b98\u65b9 CFF \u6d4b\u8bd5\u96c6\uff0c\u9ed8\u8ba4**\u5168\u91cf**\uff08\u7ea6 1.4 \u4e07\u6837\u672c\uff0c\u5f85\u6838 U1\uff09\u3002\n- **\u914d\u5bf9**\uff1a\u4e24\u6a21\u578b\u5728\u76f8\u540c\u6837\u672c\u3001\u76f8\u540c prompt\u3001\u76f8\u540c\u89e3\u7801\u8bbe\u7f6e\u4e0b\u9010\u6837\u672c\u8bc4\u5206\uff1b\u6837\u672c\u7ea7\u5339\u914d\u662f\u540e\u7eed\u914d\u5bf9\u7edf\u8ba1\u7684\u524d\u63d0\u3002\n- **\u91cd\u6570/\u968f\u673a\u6027**\uff1a\n  - \u4e3b\u7ed3\u679c\uff1agreedy\uff08temp=0\uff09\u5355\u8f68\uff0c\u786e\u5b9a\u6027\u3002\u968f\u673a\u6027\u7531\u56fa\u5b9a seed \u63a7\u5236\uff0c\u5e76\u901a\u8fc7**\u5bf9\u6837\u672c**\u505a\u914d\u5bf9 bootstrap\uff0810,000 \u6b21\uff0cseed 42\uff09\u4f30\u8ba1 CI \u4e0e p \u503c\u2014\u2014\u5373\"\u91cd\u6570\"\u4f53\u73b0\u5728\u91cd\u91c7\u6837\u7edf\u8ba1\u800c\u975e\u91cd\u590d\u751f\u6210\u3002\n  - \u53ef\u9009\uff08\u9884\u7b97\u5141\u8bb8\u65f6\uff09\uff1a\u6bcf\u6837\u672c\u751f\u6210 k=3~5 \u8f68 temp=0.8\u3001top-p=0.95 \u91c7\u6837\uff0c\u62a5\u544a pass@1 \u4ee5\u53ca\u89e3\u7801\u9c81\u68d2\u6027\u5206\u6790\u3002\n- **\u62bd\u6837\u51b3\u7b56\uff08\u7b97\u529b\u53d7\u9650\u65f6\uff09**\uff1a\u56fa\u5b9a seed 42 \u505a\u7b80\u5355\u968f\u673a\u62bd\u6837 n=1,000\uff0c\u5bfc\u51fa\u88ab\u62bd\u6837\u672c id \u5217\u8868\uff08\u5b58 JSON\uff09\u4f9b\u5ba1\u8ba1\uff1b\u82e5\u4ecd\u4e0d\u8db3\u5219 n=300 \u63a2\u7d22\u6027\u5b50\u96c6\u5e76**\u660e\u786e\u6807\u6ce8\"\u4ec5\u521d\u6b65\u8bc1\u636e\"**\u3002\u62a5\u544a\u4e2d\u6ce8\u660e\u62bd\u6837\u5bfc\u81f4 CI \u53d8\u5bbd\u5e76\u9644\u529f\u6548\u8bf4\u660e\u3002\n\n### 2.2 \u7edf\u4e00\u4efb\u52a1\u683c\u5f0f\uff08prompt \u6784\u9020\u4e0e\u4e24\u6a21\u578b\u5bf9\u9f50\uff09\n- **\u516c\u5171\u6a21\u677f\uff08\u4e24\u6a21\u578b\u5171\u7528\uff09**\uff1a\n  - CFF \u4e3b\u8f68\uff1a`concat(\u4f9d\u8d56\u6587\u4ef6\u6309\u5b98\u65b9\u987a\u5e8f) + <\u5206\u9694> + \u76ee\u6807\u6587\u4ef6\u524d\u7f00(\u81f3\u7b7e\u540d\u884c)`\u3002\n  - \u5bf9\u7167\u8f68\uff08prefix-only\uff09\uff1a\u4ec5\u76ee\u6807\u6587\u4ef6\u524d\u7f00\u3002\n  - \u5206\u9694\u7b26\u7528\u666e\u901a\u6362\u884c/\u6587\u4ef6\u8def\u5f84\u6ce8\u91ca\u5934\uff1b**\u4e0d\u4f7f\u7528\u4efb\u4f55\u6a21\u578b\u7684\u7279\u6b8a fill token**\uff08\u4e24\u6a21\u578b\u5747\u6807\u51c6\u524d\u7f00\u7eed\u5199\u63a5\u53e3\uff0c\u907f\u514d InCoder \u5f0f FIM \u5e26\u6765\u7684\u4e0d\u53ef\u6bd4\uff09\u3002\n- **\u6a21\u578b\u63a5\u53e3**\uff1aGPT-2 \u7528 `GPT2LMHeadModel`\uff08`gpt2` \u5b98\u65b9\u6743\u91cd\uff0c124M\uff09\uff1bCodeLlama \u7528 `AutoModelForCausalLM` \u52a0\u8f7d `codellama/CodeLlama-7b-hf`\uff08base \u7248\uff0c\u975e Instruct/Python \u53d8\u4f53\uff0c\u7406\u7531\uff1a\u5bf9\u9f50\"\u539f\u751f\u6c14\u4ee3\u7801\u8865\u5168\"\u80fd\u529b\u5e76\u5728 \u00a75 \u5217\u4e3a\u5047\u8bbe\uff09\u3002\u4e24\u8005\u5747\u7528\u5404\u81ea tokenizer + `generate` \u524d\u7f00\u7eed\u5199\u3002\n- **\u8f93\u5165\u957f\u5ea6\u5bf9\u9f50**\uff1a\u7edf\u4e00\u8f93\u5165\u9884\u7b97 B=1,024 token\uff08\u5bf9\u4e24\u6a21\u578b\u4e00\u81f4\u2014\u2014GPT-2 \u7a97\u53e3\u4e0a\u9650\u5373 1024\uff09\uff1bCodeLlama \u53e6\u8dd1 B=16K \u5168\u4e0a\u4e0b\u6587\u8f68\uff08\u6d88\u878d A\uff09\u3002\u7531\u4e8e\u4e24\u8005\u5206\u8bcd\u5668\u4e0d\u540c\uff0c\"1,024 token\"\u5b9e\u9645\u8986\u76d6\u5b57\u7b26\u6570\u4e0d\u540c\uff0c\u6545**\u53cc\u53e3\u5f84\u590d\u6838**\uff1a\u6309\u300ctoken \u6570\u300d\u4e0e\u300c\u5b57\u7b26\u6570\u300d\u5404\u505a\u4e00\u6b21\u7b49\u957f\u5bf9\u9f50\uff0c\u62a5\u544a\u4e24\u8005\u7ed3\u679c\u3002\n- **\u8f93\u51fa\u957f\u5ea6\u5bf9\u9f50**\uff1a`max_new_tokens` \u4e3b\u53e3\u5f84 = min(256, \u91d1\u6807 token \u6570)\uff0c\u5e76\u5728\u8bc4\u5206\u524d\u628a\u4e24\u6a21\u578b\u9884\u6d4b\u90fd\u622a\u5230\u91d1\u6807\u957f\u5ea6\uff08\u89c1 \u00a72.3\uff09\uff1b\u53e6\u8bbe\"\u4e0d\u622a\u65ad\uff08\u4e0a\u9650 256\uff09\"\u6b21\u53e3\u5f84\uff08\u6d88\u878d E\uff09\u3002\n\n### 2.3 \u8bc4\u6d4b\u7ba1\u7ebf\u7ec6\u8282\uff08\u6253\u5206\u7ba1\u7ebf\uff09\n1. **\u8f93\u51fa\u5f52\u4e00\u5316\uff08\u5bf9\u4e24\u6a21\u578b\u4e00\u81f4\uff09**\uff1a\n   a. \u53bb\u9664\u751f\u6210\u6587\u672c\u9996\u5c3e\u7a7a\u767d\u4e0e\u591a\u4f59\u5c3e\u968f\u7f29\u8fdb/\u6362\u884c\uff1bb. \u884c\u5c3e\u7edf\u4e00\u4e3a LF(CRLF\u2192LF)\uff1bc. \u622a\u53d6\u9884\u6d4b\u5230\u91d1\u6807 body \u957f\u5ea6\uff08\u5b57\u7b26\u7ea7\u4e3a\u4e3b\u53e3\u5f84\uff09\uff1bd. \u89c4\u8303\u5316 EM\uff1d\u53bb\u9664\u6240\u6709\u7a7a\u767d\u540e\u7cbe\u786e\u76f8\u7b49\uff1b\u540c\u65f6\u8bb0\u5f55\u539f\u59cb\u7cbe\u786e EM\u3002\n2. **\u6307\u6807**\uff1a\u4e3b\u6307\u6807 = per-sample ES\uff08\u5b57\u7b26\u7ea7 Levenshtein \u5f52\u4e00\u5316\uff09+ \u89c4\u8303\u5316 EM\uff1b\u8865\u5145 = BLEU/CodeBLEU\uff08\u6ce8\u660e\u975e\u5b98\u65b9\u6307\u6807\uff0c\u4ec5\u53c2\u8003\uff09\u3002\n3. **\u5b98\u65b9\u811a\u672c vs \u81ea\u5efa\uff08\u5bf9\u9f50\u65b9\u5f0f\uff09**\uff1a\n   - \u9996\u9009\uff1a\u82e5\u80fd\u83b7\u5f97\u5b98\u65b9 `evaluate.py`\uff0c\u76f4\u63a5\u8c03\u7528\u5e76\u9501\u5b9a\u5176\u7248\u672c\uff08\u8bb0\u5f55 hash\uff09\uff0c\u5b98\u65b9\u600e\u4e48\u7b97\u5c31\u600e\u4e48\u7b97\u3002\n   - \u5426\u5219\u81ea\u5efa\uff1a\u5b9e\u73b0 EM\uff08\u89c4\u8303\u5316\u4e0e\u539f\u59cb\u4e24\u79cd\uff09\u4e0e ES\uff08Levenshtein\uff09\uff0c\u5c06\u5b9e\u73b0\u9501\u5b9a\u5728\u4ed3\u5e93\u5185\uff0c\u5e76\u7528**\u624b\u5de5\u6837\u4f8b\u5355\u5143\u6d4b\u8bd5**\u5bf9\u9f50\u5b98\u65b9\u5b9a\u4e49\uff08\u4f8b\u5982\u7ed9\u5b9a gold=`return a+b`\uff0c\u5bf9\u82e5\u5e72\u9884\u6d4b\u53d8\u4f53\u65ad\u8a00\u671f\u671b\u7684 ES/EM \u503c\uff09\u3002\u4e24\u6a21\u578b\u5171\u4eab\u540c\u4e00\u5957\u6253\u5206\u51fd\u6570\uff0c\u4fdd\u8bc1\u76f8\u5bf9\u6bd4\u8f83\u96f6\u504f\u5dee\u3002\n   - \u65e0\u8bba\u54ea\u79cd\uff0c\u62a5\u544a\u58f0\u660e\u53e3\u5f84\uff1b\u81ea\u5efa\u65f6\u5728\u62a5\u544a\u4e2d\u7ed9\u51fa\"\u4e0e\u5b98\u65b9\u5b9a\u4e49\u7684\u5dee\u5f02\u5217\u8868\"\u3002\n\n### 2.4 \u7edf\u8ba1\u4e0e\u663e\u8457\u6027\u68c0\u9a8c\n- \u914d\u5bf9 bootstrap\uff0810,000 \u6b21\uff0cseed 42\uff09\u2192 \u4e24\u6a21\u578b ES \u5747\u503c\u5dee/\u4e2d\u4f4d\u6